function load(){try{const x=JSON.parse(localStorage.getItem(KEY));if(!x)return fresh();if(x.version===15)return x;const y=fresh();Object.assign(y,x);y.version=15;y.settings={...y.settings,...(x.settings||{})};y.locationData={...y.locationData,...(x.locationData||{})};return y}catch{return fresh()}}
function save(){localStorage.setItem(KEY,JSON.stringify(db))}
function user(){return db.session?db.users.find(x=>x.id===db.session):null}
function isAdminRole(r){return r==='admin'||r==='super_admin'||String(r||'').endsWith('_admin')}
function requireUser(role){const u=user();if(!u){authModal(role==='admin'?'admin':'login');return false}if(role==='admin'&&!isAdminRole(u.role)){toast('This area requires authorized Admin access');return false}if(role&&role!=='admin'&&!([role,'super_admin','admin'].includes(u.role))){toast('This area requires '+role+' access');return false}return true}
