function productCard(p){return `<article class="product"><div class="pimg"><img src="${esc(p.image)}" alt="${esc(p.name)}" onerror="this.src='${A.primary}'"></div><div class="pbody"><div class="rating">★ ${p.rating} (${p.reviews})</div><h3>${esc(p.name)}</h3><div class="muted">${esc(p.seller)} • ${esc(p.sellerType)}</div><div><span class="price">${money(p.price)}</span> <span class="strike">${money(p.mrp)}</span> <span class="badge">${p.discount}% off</span></div><div class="actions"><button class="small primary" onclick="JB.add('${p.id}')">Add to Cart</button><button class="small" onclick="JB.go('product/${p.id}')">View</button><button class="small" onclick="JB.wish('${p.id}')">♡</button></div></div></article>`}
